// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address newOwner) public {
        // Ensure the caller is the owner for the transferOwnership
        vm.assume(newOwner != address(0));
        vm.prank(c.owner());
        c.transferOwnership(newOwner);
        // Now call owned() as the original owner (which is now newOwner)
        vm.prank(newOwner);
        c.owned();
        assertTrue(c.owner() == newOwner);
    }
}

